// Pretends to be several agrisoil sensors at once.
// Same topics and payloads as agrisoil/send_mqtt.ino.
// Add a sensor = add a name to AGRI_DEVICES (env var), no other change.
const devices = (env.get('AGRI_DEVICES') || 'Alat1,Alat2,Alat3').split(',').map(d => d.trim()).filter(Boolean);
const BASE_LAT = Number(env.get('AGRI_LAT') || -6.200000); // set to your field
const BASE_LNG = Number(env.get('AGRI_LNG') || 106.816666);

function walk(v, step, min, max) {
    v += (Math.random() * 2 - 1) * step;
    return Math.min(max, Math.max(min, v));
}

function pad(x) { return String(x).padStart(2, '0'); }
// "YYYY-MM-DD HH:MM:SS" in WIB (UTC+7), like the firmware
const t = new Date(Date.now() + 7 * 3600 * 1000);
const waktu = t.getUTCFullYear() + '-' + pad(t.getUTCMonth() + 1) + '-' + pad(t.getUTCDate()) + ' ' +
    pad(t.getUTCHours()) + ':' + pad(t.getUTCMinutes()) + ':' + pad(t.getUTCSeconds());

const all = context.get('state') || {};
const out = [];

devices.forEach((id, i) => {
    // every sensor starts somewhere different, so the charts differ
    let s = all[id] || {
        n: 120 + i * 60, p: 10 + i * 4, k: 90 + i * 20, ph: 5.8 + i * 0.4, moist: 35 + i * 10,
        lat: BASE_LAT + i * 0.002, lng: BASE_LNG + i * 0.002
    };
    s.n = walk(s.n, 10, 60, 350);
    s.p = walk(s.p, 1, 5, 30);
    s.k = walk(s.k, 5, 70, 170);
    s.ph = walk(s.ph, 0.05, 5.0, 8.0);
    s.moist = walk(s.moist, 2, 20, 90);
    all[id] = s;

    // Raw ADC counts, back-calculated from the ADS1115 calibration.
    const npk1 = Math.round((46510 - s.n) / 8.1731);
    const npk2 = npk1 + Math.round(Math.random() * 40 - 20);
    const moistRaw = Math.round(11940 - (s.moist / 100) * (11940 - 4680));
    const phRaw = Math.round(300 + Math.random() * 50);
    const gpsValid = Math.random() > 0.1; // 10% of readings without a GPS fix

    const base = 'agrisoil/' + id + '/';
    const reading = {
        device: id, waktu: waktu,
        n: +s.n.toFixed(2), p: +s.p.toFixed(2), k: +s.k.toFixed(2),
        ph: +s.ph.toFixed(2), moist: +s.moist.toFixed(2),
        npk1_raw: npk1, npk2_raw: npk2, moist_raw: moistRaw, ph_raw: phRaw,
        in_soil: true,
        lat: gpsValid ? +s.lat.toFixed(6) : null,
        lng: gpsValid ? +s.lng.toFixed(6) : null
    };

    out.push({ topic: base + 'reading', payload: JSON.stringify(reading), retain: true });
    out.push({ topic: base + 'val/moist', payload: s.moist.toFixed(2) });
    out.push({ topic: base + 'val/ph', payload: s.ph.toFixed(2) });
    out.push({ topic: base + 'val/nit', payload: s.n.toFixed(2) });
    out.push({ topic: base + 'val/phos', payload: s.p.toFixed(2) });
    out.push({ topic: base + 'val/kal', payload: s.k.toFixed(2) });
    out.push({ topic: base + 'raw/moist', payload: String(moistRaw) });
    out.push({ topic: base + 'raw/ph', payload: String(phRaw) });
    out.push({ topic: base + 'raw/npk1', payload: String(npk1) });
    out.push({ topic: base + 'raw/npk2', payload: String(npk2) });
    if (gpsValid) {
        out.push({ topic: base + 'loc/lat', payload: s.lat.toFixed(6) });
        out.push({ topic: base + 'loc/lng', payload: s.lng.toFixed(6) });
    }
});

context.set('state', all);
return [out];

// The ESP32 expects plain text: just the port number.
// Real setup: today's ngrok TCP port. Local test: the broker's port.
msg.payload = String(global.get('ngrokPort') || env.get('AGRI_MQTT_PORT') || 1883);
msg.headers = { 'Content-Type': 'text/plain' };
return msg;
